<template>
  <PageShell title="提成与奖金" description="维护提成默认单价，按数量计算提成，并支持同一员工多笔奖金记录。" @refresh="load">
    <div class="toolbar"><el-date-picker v-model="store.startDate" value-format="YYYY-MM-DD" placeholder="开始日期" clearable @change="load"/><span>至</span><el-date-picker v-model="store.endDate" value-format="YYYY-MM-DD" placeholder="结束日期" clearable @change="load"/></div>
    <el-tabs v-model="tab">
      <el-tab-pane label="提成记录" name="records"><div class="toolbar"><el-button type="primary" @click="openCommission()">新增提成</el-button></div><el-table :data="store.commissions" empty-text="暂无提成记录"><el-table-column prop="date" label="日期"/><el-table-column label="员工"><template #default="{row}">{{nameOf(row.employeeId)}}</template></el-table-column><el-table-column label="类型"><template #default="{row}">{{commissionName(row.commissionTypeId)}}</template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column prop="unitPrice" label="单价"/><el-table-column label="金额"><template #default="{row}"><span class="money">¥{{row.amount.toFixed(2)}}</span></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" :disabled="!!row.lockedAt" @click="openCommission(row)">编辑</el-button><el-button link type="danger" :disabled="!!row.lockedAt" @click="removeCommission(row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="提成类型" name="types"><div class="toolbar"><el-input v-model="typeForm.name" placeholder="类型"/><el-input v-model="typeForm.unitName" placeholder="单位"/><el-input-number v-model="typeForm.unitPrice" :min="0"/><el-switch v-model="typeForm.active" active-text="启用" inactive-text="停用"/><el-button type="primary" :loading="store.saving" @click="saveType">{{typeEditingId?'保存修改':'新增类型'}}</el-button><el-button v-if="typeEditingId" @click="resetType">取消编辑</el-button></div><el-table :data="store.commissionTypes"><el-table-column prop="name" label="类型"/><el-table-column prop="unitName" label="单位"/><el-table-column prop="unitPrice" label="默认单价"/><el-table-column label="状态"><template #default="{row}">{{row.active?'启用':'停用'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="editType(row)">编辑</el-button><el-button link type="danger" @click="removeType(row.id)">删除/停用</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="奖金记录" name="bonuses"><div class="toolbar"><el-button type="primary" @click="openBonus()">新增奖金</el-button></div><el-table :data="store.bonuses" empty-text="暂无奖金记录"><el-table-column prop="date" label="日期"/><el-table-column label="员工"><template #default="{row}">{{nameOf(row.employeeId)}}</template></el-table-column><el-table-column label="金额"><template #default="{row}"><span class="money">¥{{row.amount.toFixed(2)}}</span></template></el-table-column><el-table-column prop="reason" label="发放原因"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" :disabled="!!row.lockedAt" @click="openBonus(row)">编辑</el-button><el-button link type="danger" :disabled="!!row.lockedAt" @click="removeBonus(row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
    </el-tabs>
  </PageShell>
  <el-dialog v-model="commissionVisible" :title="commissionEditingId?'编辑提成':'新增提成'" width="600px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="员工" required><el-select v-model="commissionForm.employeeId"><el-option v-for="row in store.activeEmployees" :key="row.id" :label="row.name" :value="row.id"/></el-select></el-form-item><el-form-item label="提成类型" required><el-select v-model="commissionForm.commissionTypeId"><el-option v-for="row in store.commissionTypes.filter(item=>item.active)" :key="row.id" :label="`${row.name} ¥${row.unitPrice}/${row.unitName}`" :value="row.id"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker v-model="commissionForm.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="数量"><el-input-number v-model="commissionForm.quantity" :min="0"/></el-form-item><el-form-item label="手工单价（留空使用默认值）"><el-input-number v-model="commissionForm.unitPrice" :min="0"/></el-form-item><el-form-item label="备注"><el-input v-model="commissionForm.remark"/></el-form-item></el-form><template #footer><el-button @click="commissionVisible=false">取消</el-button><el-button type="primary" :loading="store.saving" @click="saveCommission">保存</el-button></template></el-dialog>
  <el-dialog v-model="bonusVisible" :title="bonusEditingId?'编辑奖金':'新增奖金'" width="560px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="员工" required><el-select v-model="bonusForm.employeeId"><el-option v-for="row in store.activeEmployees" :key="row.id" :label="row.name" :value="row.id"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker v-model="bonusForm.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="金额"><el-input-number v-model="bonusForm.amount" :min="0"/></el-form-item><el-form-item label="发放原因" required><el-input v-model="bonusForm.reason"/></el-form-item></el-form><template #footer><el-button @click="bonusVisible=false">取消</el-button><el-button type="primary" :loading="store.saving" @click="saveBonus">保存</el-button></template></el-dialog>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import dayjs from 'dayjs'
import PageShell from './EmployeeAttendancePageShell.vue'
import { useEmployeeAttendanceStore } from '@/stores/employeeAttendance'
import * as api from '@/api/employeeAttendance'
import type { BonusRecord, CommissionRecord, CommissionType } from '@/types/employeeAttendance'

const store = useEmployeeAttendanceStore(), tab = ref('records'), commissionVisible = ref(false), bonusVisible = ref(false), formError = ref('')
const typeEditingId = ref(''), commissionEditingId = ref(''), bonusEditingId = ref('')
const typeForm = reactive({ name: '', unitName: '', unitPrice: 0, active: true })
const commissionForm = reactive({ employeeId: '', commissionTypeId: '', date: dayjs().format('YYYY-MM-DD'), quantity: 1, unitPrice: undefined as number | undefined, remark: '' })
const bonusForm = reactive({ employeeId: '', date: dayjs().format('YYYY-MM-DD'), amount: 0, reason: '' })
const errorText = (error: unknown, fallback: string) => error instanceof Error ? error.message : fallback
function nameOf(id: string) { return store.employees.find(row => row.id === id)?.name || '-' }
function commissionName(id: string) { return store.commissionTypes.find(row => row.id === id)?.name || '-' }
async function load() { await store.loadCompensation().catch(() => undefined) }
function openCommission(row?: CommissionRecord) { commissionEditingId.value = row?.id || ''; Object.assign(commissionForm, row ? { employeeId: row.employeeId, commissionTypeId: row.commissionTypeId, date: row.date, quantity: row.quantity, unitPrice: row.unitPrice, remark: row.remark || '' } : { employeeId: store.employeeId || store.activeEmployees[0]?.id || '', commissionTypeId: store.commissionTypes.find(item => item.active)?.id || '', date: dayjs().format('YYYY-MM-DD'), quantity: 1, unitPrice: undefined, remark: '' }); formError.value = ''; commissionVisible.value = true }
function openBonus(row?: BonusRecord) { bonusEditingId.value = row?.id || ''; Object.assign(bonusForm, row ? { employeeId: row.employeeId, date: row.date, amount: row.amount, reason: row.reason } : { employeeId: store.employeeId || store.activeEmployees[0]?.id || '', date: dayjs().format('YYYY-MM-DD'), amount: 0, reason: '' }); formError.value = ''; bonusVisible.value = true }
async function saveCommission() { try { await store.run(() => api.saveCommission({ ...commissionForm }, commissionEditingId.value || undefined), true); commissionVisible.value = false; await load() } catch (error) { formError.value = errorText(error, '提成保存失败') } }
async function saveBonus() { try { await store.run(() => api.saveBonus({ ...bonusForm }, bonusEditingId.value || undefined), true); bonusVisible.value = false; await load() } catch (error) { formError.value = errorText(error, '奖金保存失败') } }
function resetType() { typeEditingId.value = ''; Object.assign(typeForm, { name: '', unitName: '', unitPrice: 0, active: true }) }
function editType(row: CommissionType) { typeEditingId.value = row.id; Object.assign(typeForm, { name: row.name, unitName: row.unitName, unitPrice: row.unitPrice, active: row.active }) }
async function saveType() { if (!typeForm.name.trim() || !typeForm.unitName.trim()) { store.setError('请填写类型和单位'); return } try { await store.run(() => api.saveCommissionType({ ...typeForm }, typeEditingId.value || undefined), true); resetType(); await load() } catch (error) { store.setError(errorText(error, '提成类型保存失败')) } }
async function removeCommission(id: string) { try { await store.run(() => api.deleteCommission(id), true); await load() } catch (error) { store.setError(errorText(error, '提成记录删除失败')) } }
async function removeBonus(id: string) { try { await store.run(() => api.deleteBonus(id), true); await load() } catch (error) { store.setError(errorText(error, '奖金记录删除失败')) } }
async function removeType(id: string) { try { await store.run(() => api.deleteCommissionType(id), true); await load() } catch (error) { store.setError(errorText(error, '提成类型删除或停用失败')) } }
onMounted(load)
</script>
